<script setup lang="ts">
import {ref,reactive,watch,onBeforeUnmount} from 'vue';
import {Search,RefreshCw,AlertCircle,ChevronRight,ChevronLeft,CheckCircle2} from 'lucide-vue-next';
import {api} from './api';
import {defaultReviewQuery,reviewParams,type ReviewQuery} from './reviewQuery';
const props=defineProps<{courseId:number;teacher:boolean;courseLabel:string;filters:ReviewQuery;busy:boolean}>();
const emit=defineEmits(['open','filters','summary']);
const catalog=ref<any>({assignments:[],authors:[]});
const filters=reactive({...props.filters}),data=ref<any>(null),loading=ref(true),error=ref('');let sequence=0,alive=true,timer:ReturnType<typeof setTimeout>|undefined;
const tabs=[['ALL','全部提交'],['PENDING','待评审'],['GRADED','已评价']];
function count(key:string){return data.value?.summary?.[key]??'—';}
function tabCount(key:string){return count(key==='PENDING'?'pending_count':key==='GRADED'?'graded_count':'submission_count');}
async function load(){clearTimeout(timer);const g=++sequence,snapshot={...filters};loading.value=true;error.value='';data.value=null;emit('filters',snapshot);try{const result=await api(`/courses/${props.courseId}/review-workbench?${reviewParams(snapshot)}`);if(!alive||g!==sequence)return;data.value=result;catalog.value={assignments:result.assignments,authors:result.authors};if(result.page!==filters.page){filters.page=result.page;return;}emit('summary',result.summary);}catch(e:any){if(alive&&g===sequence)error.value=e.message||'暂时无法读取批改队列';}finally{if(alive&&g===sequence)loading.value=false;}}
function reset(){Object.assign(filters,defaultReviewQuery());}
function open(row:any){if(!loading.value&&!props.busy&&data.value)emit('open',{id:row.id,filters:{...filters}});}
watch(()=>[filters.q,filters.assignmentId,filters.authorId,filters.state,filters.drafts,filters.evidence,filters.versions,filters.sort],()=>{sequence++;data.value=null;loading.value=true;if(filters.page!==1)filters.page=1;clearTimeout(timer);timer=setTimeout(load,250);});
watch(()=>filters.page,()=>{sequence++;data.value=null;loading.value=true;clearTimeout(timer);timer=setTimeout(load,0);});
onBeforeUnmount(()=>{alive=false;sequence++;clearTimeout(timer);});load();
function fmt(s:string){return new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});}
</script>
<template><section class="page review-workbench"><div class="page-heading"><div><span class="eyebrow">教师评审工作区</span><h1>批改中心</h1><p>按真实提交版本处理评审。只读查询不会发布评价、作品或更新草稿。</p></div><button class="btn secondary" :disabled="loading" @click="load"><RefreshCw :size="16"/>刷新队列</button></div>
<p class="small-label">{{courseLabel}} · {{teacher?'评分草稿仅本人可见':'助教只读评审，不显示教师评分草稿'}}</p>
<div class="review-stats" aria-label="评审范围概览"><article><span>提交版本</span><strong>{{count('submission_count')}}</strong></article><article><span>待正式评价</span><strong>{{count('pending_count')}}</strong></article><article><span>已正式评价</span><strong>{{count('graded_count')}}</strong></article><article v-if="teacher"><span>我的评分草稿</span><strong>{{count('my_draft_count')}}</strong></article><article><span>有争议证据的提交</span><strong>{{count('disputed_evidence_count')}}</strong></article></div>
<p class="muted review-scope-note">概览按关键词、作业、作者和版本范围统计；不随评价、草稿、证据筛选或翻页改变。计数单位为提交版本，不是学生人数；已有草稿不代表已评价。</p>
<div class="review-toolbar"><div class="list-tabs" role="group" aria-label="评审筛选"><button v-for="[key,label] in tabs" :key="key" :class="{active:filters.state===key}" :aria-pressed="filters.state===key" @click="filters.state=key">{{label}}<span>{{tabCount(key)}}</span></button></div><label class="search-box"><Search :size="16"/><input v-model="filters.q" maxlength="80" aria-label="搜索评审提交" placeholder="搜索作品、学生或作业"/></label></div>
<div class="review-filters"><label>作业<select v-model="filters.assignmentId" aria-label="按作业筛选评审"><option value="0">全部作业</option><option v-for="a in catalog.assignments" :key="a.id" :value="String(a.id)">{{a.title}}</option></select></label><label>作者<select v-model="filters.authorId" aria-label="按作者筛选评审"><option value="0">全部作者</option><option v-for="a in catalog.authors" :key="a.id" :value="String(a.id)">{{a.display_name}}{{a.current_member?'':'（历史成员）'}}</option></select></label><label>版本范围<select v-model="filters.versions" aria-label="评审版本范围"><option value="ALL">全部提交版本</option><option value="LATEST">每篇作品最新提交</option></select></label><label v-if="teacher">评分草稿<select v-model="filters.drafts" aria-label="筛选我的评分草稿"><option value="ALL">全部草稿状态</option><option value="MINE">有我的草稿</option><option value="NONE">无我的草稿</option></select></label><label>证据状态<select v-model="filters.evidence" aria-label="按证据状态筛选评审"><option value="ALL">全部证据状态</option><option value="PENDING">有待核验证据</option><option value="DISPUTED">有争议证据</option></select></label><label>排序<select v-model="filters.sort" aria-label="评审排序"><option value="oldest">最早提交优先</option><option value="recent">最近提交优先</option><option value="evidence">证据争议优先</option></select></label><button class="text-btn" @click="reset">清除评审筛选</button></div>
<p v-if="filters.versions==='LATEST'" class="review-range-warning">当前仅显示每篇作品最新提交；旧版本仍可能有待评审记录，切换“全部提交版本”可查看。此筛选不会删除或自动评价旧版本。</p>
<div v-if="error" role="alert" class="review-load-error"><AlertCircle :size="18"/>{{error}}<button class="btn secondary" @click="load">重试读取队列</button></div>
<div class="list-card review-results" :aria-busy="loading"><p v-if="loading" role="status" class="empty">正在读取评审范围…</p><template v-else-if="data"><div class="queue-column-head"><span>作品 / 作者</span><span>评价状态</span><span>提交时间</span></div><button v-for="row in data.items" :key="row.id" class="review-row" :disabled="busy" @click="open(row)"><span class="avatar">{{row.author_name.slice(0,1)}}</span><div class="review-row-text"><strong>{{row.title}}</strong><p>{{row.author_name}} · {{row.assignment_title}} · v{{row.version_no}} <span v-if="!row.is_latest">· 历史提交</span></p><p v-if="row.pending_evidence||row.disputed_evidence" class="review-evidence-status">待核验 {{row.pending_evidence}} · 有争议 {{row.disputed_evidence}}</p><p v-if="teacher&&row.review_draft_updated_at">{{row.draft_stale?'我的草稿需按新评价复核':'有我的评分草稿'}} · {{fmt(row.review_draft_updated_at)}}</p></div><span class="badge" :class="row.q_final==null?'orange':'green'">{{row.q_final==null?(row.review_draft_updated_at?'待评审 · 有草稿':'待评审'):Number(row.q_final).toFixed(1)+' 分'}}</span><span class="row-time">{{fmt(row.created_at)}}</span><ChevronRight :size="18"/></button><div v-if="!data.items.length" class="empty"><CheckCircle2 :size="30"/><h2>{{data.summary.submission_count?'没有匹配的提交':'当前范围尚无提交'}}</h2><p>可调整筛选或清除条件；空列表不代表已完成全部课程评审。</p></div><footer class="review-pagination"><span>{{data.total}} 份匹配提交 · 第 {{data.page}} / {{Math.max(1,Math.ceil(data.total/data.pageSize))}} 页</span><div><button class="btn secondary" :disabled="loading||data.page<=1" @click="filters.page--"><ChevronLeft :size="15"/>上一页评审</button><button class="btn secondary" :disabled="loading||data.page*data.pageSize>=data.total" @click="filters.page++">下一页评审<ChevronRight :size="15"/></button></div></footer></template></div><p class="muted">“下一份待评审”按当前范围实时选择另一份无正式评价的提交，不锁定、不自动评分；切换前须先保存或处理当前评分草稿。排序相同时用提交编号稳定排序。</p></section></template>
<style scoped>
.review-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:12px;margin-top:22px}.review-stats article{border:1px solid var(--border);background:var(--paper);border-radius:10px;padding:16px}.review-stats span{display:block;color:var(--muted);font-size:12px}.review-stats strong{display:block;font-size:28px;margin-top:10px}.review-scope-note{margin:16px 0;line-height:1.8;font-size:12px}.review-filters{display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;margin:16px 0 22px}.review-filters label{display:grid;gap:7px;flex:1 1 150px;min-width:0;font-size:12px;color:var(--muted)}.review-filters select{width:100%;min-width:0;border:1px solid var(--border);background:var(--paper);color:var(--text);border-radius:7px;padding:10px}.review-row-text{min-width:0;overflow-wrap:anywhere}.review-row-text p{line-height:1.7}.review-row-text strong{overflow-wrap:anywhere}.review-pagination{padding:16px;display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:1px solid var(--border);color:var(--muted);font-size:12px}.review-pagination>div{display:flex;gap:8px}.review-load-error{display:flex;gap:10px;align-items:center;padding:16px;color:var(--danger,#cc3333)}.review-range-warning{padding:12px;background:var(--surface);border-left:3px solid var(--accent);line-height:1.8}.review-evidence-status{color:var(--muted)}@media(max-width:650px){.review-toolbar{display:flex;flex-direction:column;align-items:stretch}.review-toolbar .search-box{width:100%}.review-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.review-workbench .queue-column-head{display:none}.review-workbench .review-row{grid-template-columns:32px minmax(0,1fr) auto;gap:10px}.review-row .row-time{grid-column:2}.review-row>svg{display:none}.review-row .badge{font-size:10px;max-width:90px;white-space:normal}.review-pagination{flex-direction:column;align-items:flex-start}.review-pagination>div{width:100%;justify-content:space-between}.review-filters label{flex-basis:135px}.review-filters select{max-width:100%}}
</style>
